    Vec GetPackPosition() { ++g_defRefs; Vec v = { def.CardWidth * def.PackOffsetX, def.CardHeight * def.PackOffsetY, 0.0f }; --g_defRefs; return v; }
    void CardsMoving()
    {
        ++g_defRefs;
        for (unsigned k = 0; k < npack; ++k)
            if (pack[k]->Moving == true) { --g_defRefs; return; }
